sed -i 's/"Fifo": false, "ContentBasedDeduplication": false,$/"Fifo": false, "ContentBasedDeduplication": false, "MaxMessageBytes": 1024,/' tests/queues.rs && cat >> tests/queues.rs <<'E'

#[test]
fn max_message_bytes_is_validated_and_part_of_create_equality() {
    let mut h = Harness::new();
    for bad in [json!(0), json!(1025), json!("5"), json!(5.0)] {
        assert_eq!(
            h.err(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": bad}})),
            "InvalidParameterValue"
        );
    }
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 5}}));
    assert_eq!(attrs(&mut h, "q")["MaxMessageBytes"], json!(5));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 5}}));
    assert_eq!(
        h.err(json!({"Command": "CreateQueue", "QueueName": "q"})),
        "QueueAlreadyExists"
    );
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1024}}));
    assert_eq!(attrs(&mut h, "q")["MaxMessageBytes"], json!(1024));
}

#[test]
fn max_message_bytes_limits_bodies_in_utf8_bytes() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 4}}));
    let send = |body: &str| json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
    h.ok(send("abcd"));
    // Two characters, four bytes.
    h.ok(send("éé"));
    assert_eq!(h.err(send("abcde")), "InvalidParameterValue");
    assert_eq!(h.err(send("ééa")), "InvalidParameterValue");
    // The rule comes before the FIFO rules of the queue type.
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcde", "GroupId": "g"})),
        "InvalidParameterValue"
    );
    // The 1024 byte rule of step 3 still comes first and a missing queue second.
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "nope", "Body": "abcde"})),
        "QueueDoesNotExist"
    );
}

#[test]
fn lowering_max_message_bytes_keeps_queued_messages() {
    let mut h = Harness::new();
    create(&mut h, "q");
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcdefgh"}));
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 2}}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], json!("abcdefgh"));
}
E
