    h.ok(send("éé"));
    assert_eq!(h.err(send("abcde")), "InvalidParameterValue");
    assert_eq!(h.err(send("ééa")), "InvalidParameterValue");
    // The rule comes before the queue type rules, which would give UnsupportedOperation.
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcde", "GroupId": "g"})),
        "InvalidParameterValue"
    );
    // A missing queue is found before the rule is applied.
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "nope", "Body": "abcde"})),
        "QueueDoesNotExist"
    );
}

